                pos = (pos + 1) & 1023;
            t.keys[pos] = n;
            t.idx[pos] = static_cast<FIT_UINT16>(i + 1);
        }
        return t;
    }();
    FIT_UINT16 pos = static_cast<FIT_UINT16>((num * 2654435761u) >> 22) & 1023;
    while (table.idx[pos] != 0) {
        if (table.keys[pos] == num)
            return &mesgs[table.idx[pos] - 1];
        pos = (pos + 1) & 1023;
    }
    return NULL;
}
